   121	void FrameConsole::DidFailLoading(DocumentLoader* loader,
   122	                                  uint64_t request_identifier,
   123	                                  const ResourceError& error) {
   124	  // Report failures only.
   125	  if (error.IsCancellation() || error.IsUnactionableTrustTokensStatus())
   126	    return;
   127	
   128	  if (error.WasBlockedByORB()) {
   129	    // ORB loading errors are reported from the network service directly to
   130	    // DevTools (CorsURLLoader::ReportOrbErrorToDevTools).
   131	    return;
   132	  }
   133	
   134	  // Reduce noise in the DevTools console due to CORS policy errors.
   135	  // See http://crbug.com/375357425.
   136	  if (error.CorsErrorStatus() &&
   137	      base::FeatureList::IsEnabled(features::kDevToolsImprovedNetworkError)) {
   138	    return;
   139	  }
   140	
   141	  StringBuilder message;
   142	  message.Append("Failed to load resource");
   143	  if (!error.LocalizedDescription().empty()) {
   144	    message.Append(": ");
   145	    message.Append(error.LocalizedDescription());
   146	  }
   147	  auto* console_message = MakeGarbageCollected<ConsoleMessage>(
   148	      mojom::blink::ConsoleMessageSource::kNetwork,
   149	      mojom::blink::ConsoleMessageLevel::kError, message.ToString(),
   150	      error.FailingURL(), loader, request_identifier);
   151	  if (error.CorsErrorStatus()) {
   152	    console_message->SetCategory(mojom::blink::ConsoleMessageCategory::Cors);
   153	  }
   154	  AddMessageToStorage(console_message);
   155	}
