   122	  void reportCall(ConsoleAPIType type,
   123	                  std::span<const v8::Local<v8::Value>> arguments) {
   124	    if (!groupId()) return;
   125	    // Depending on the type of the console message, we capture only parts of
   126	    // the stack trace, or no stack trace at all.
   127	    std::unique_ptr<V8StackTraceImpl> stackTrace;
   128	    switch (type) {
   129	      case ConsoleAPIType::kTrace:
   130	        // The purpose of `console.trace()` is to output a stack trace to the
   131	        // developer tools console, therefore we should always strive to
   132	        // capture a full stack trace, even before any debugger is attached.
   133	        stackTrace = m_inspector->debugger()->captureStackTrace(true);
   134	        break;
   135	
   136	      case ConsoleAPIType::kTimeEnd:
   137	        // The `console.time()` and `console.timeEnd()` APIs are meant for
   138	        // performance investigations, and therefore it's important to reduce
   139	        // the total overhead of these calls, but also make sure these APIs
   140	        // have consistent performance overhead. In order to guarantee that,
   141	        // we always capture only the top frame, otherwise the performance
   142	        // characteristics of `console.timeEnd()` would differ based on the
   143	        // current call depth, which would skew the results.
   144	        //
   145	        // See https://crbug.com/41433391 for more information.
   146	        stackTrace = V8StackTraceImpl::capture(m_inspector->debugger(), 1);
   147	        break;
   148	
   149	      default:
   150	        // All other APIs get a full stack trace only when the debugger is
   151	        // attached, otherwise record only the top frame.
   152	        stackTrace = m_inspector->debugger()->captureStackTrace(false);
   153	        break;
   154	    }
   155	    std::unique_ptr<V8ConsoleMessage> message =
   156	        V8ConsoleMessage::createForConsoleAPI(
   157	            context(), contextId(), groupId(), m_inspector,
   158	            m_inspector->client()->currentTimeMS(), type, arguments,
   159	            consoleContextToString(isolate(), m_consoleContext),
   160	            std::move(stackTrace));
   161	    if (!groupId()) return;
   162	    consoleMessageStorage()->addMessage(std::move(message));
   163	  }
